//! 🧪️ Actual Job admission preserves native Energy ownership through every source stage and token cancellation.
use super::*;
use semio_framework_job::*;
pub(crate) const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096};
pub(crate) fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(9811),Generation(3),RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30)}
pub(crate) fn call<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native Energy source physical receipt: {p:?}; failure {:?}",result.as_ref().err());result.unwrap()}
fn close_source(source:&mut Option<Box<EnergyNativeInitialSource>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for index in 0..1048576{if source.as_ref().unwrap().terminal_is_empty(){break}call(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(cx)));assert!(index<1048575);}call(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=EnergyNativeInitialSource::boxed_release_demands();close_original_retained_step(cx,d,|_|{source.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})}));}
pub(crate) fn close_decoder(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}}
#[test]fn original_energy_initial_source_denials_foreign_caller_and_all_cancel_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(law["maximumCopyBytes"],TURN.maximum_copy_bytes);for cut in law["cancelCuts"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;assert!(call(&mut caller,&mut decoder,TURN,|cx|EnergyNativeInitialSource::admit(cx,&mut source)));let mut output=None;for _ in 0..cut.as_u64().unwrap(){if output.is_some(){break}let source=source.as_mut().unwrap();let d=source.cursor.demand(source.body.unwrap_or(4096)).unwrap();for axis in 0..5{let value=[1,d.copy_bytes+if source.body.is_none(){size_of::<Option<usize>>()}else{0},d.capacity_bytes,d.release_bytes,d.depth+1][axis];if value==0{continue}let mut denied=TURN;match axis{0=>denied.maximum_items=value-1,1=>denied.maximum_copy_bytes=value-1,2=>denied.maximum_capacity_bytes=value-1,3=>denied.maximum_release_bytes=value-1,_=>denied.maximum_depth=value-1};call(&mut caller,&mut decoder,denied,|cx|source.advance(cx,&mut output));assert_eq!(caller.receipt(),RetainedCloneProgress::default());}call(&mut caller,&mut decoder,TURN,|cx|source.advance(cx,&mut output));}assert!(output.is_none());let mut foreign=OriginalJobDecodeOwner::empty();assert!(caller.turn_with_decoder(TURN,&mut foreign,|cx|source.as_mut().unwrap().advance(cx,&mut output)).is_err());caller.cancel().cancel_now();close_source(&mut source,&mut caller,&mut decoder);close_decoder(&mut caller,&mut decoder);caller.retire(TURN);}}
#[test]fn original_energy_initial_source_transfers_the_real_persistent_model(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;call(&mut caller,&mut decoder,TURN,|cx|EnergyNativeInitialSource::admit(cx,&mut source));let mut output=None;for index in 0..128{if call(&mut caller,&mut decoder,TURN,|cx|source.as_mut().unwrap().advance(cx,&mut output)){break}assert!(index<127);}let model=output.as_ref().unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(model.schema.get(),law["schema"].as_str().unwrap());assert_eq!(model.model.identity.get().run_period.get().year,law["year"].as_i64().unwrap()as u16);assert!(model.weather_link.get().is_none());assert!(model.referenced_model.get().is_none());close_source(&mut source,&mut caller,&mut decoder);let mut close=None;call(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=fixed(2*size_of::<EnergyModelSnapshot>()+size_of::<semio_framework_value::retirement::controlled::ControlledRetirement<EnergyModelSnapshot>>());close_original_retained_step(cx,d,|_|{close=Some(semio_framework_value::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(error,_)|error)?);Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})}));for index in 0..1048576{let owner=close.as_mut().unwrap();if owner.terminal_is_empty(){break}call(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let selected=owner.select(4096)?;close_original_retained_step(cx,selected.demands(),|g|selected.step(g))}));assert!(index<1048575);}close_decoder(&mut caller,&mut decoder);caller.retire(TURN);}
